<?php
namespace App\Http\Controllers;
use App\Models\Department;use App\Models\User;use App\Services\AuditService;use App\Services\XlsxService;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class ImportExportController extends Controller {
 public function usersExport(Request $r,XlsxService $xlsx){abort_unless($r->user()->role==='super-admin',403);$rows=User::with('department:id,name')->orderBy('id')->get()->map(fn($u)=>[$u->name,$u->email,$u->phone??'',$u->role,$u->status??'active',$u->department?->name??'',$u->preferred_language??'en'])->all();$tmp=tempnam(sys_get_temp_dir(),'users_').'.xlsx';$xlsx->write(['Name','Email','Phone','Role','Status','Department','Language'],$rows,$tmp);return response()->download($tmp,'karyalay-users-'.date('Ymd-His').'.xlsx')->deleteFileAfterSend(true);}
 public function usersImport(Request $r,XlsxService $xlsx,AuditService $audit){abort_unless($r->user()->role==='super-admin',403);$r->validate(['file'=>'required|file|mimes:xlsx|max:10240']);$rows=$xlsx->read($r->file('file')->getRealPath(),5000,20);abort_unless(count($rows)>=2,422,'XLSX has no data rows.');$headers=array_map(fn($v)=>strtolower(trim((string)$v)),$rows[0]);$created=0;$skipped=0;foreach(array_slice($rows,1) as $row){$data=[];foreach($headers as $i=>$h)$data[$h]=trim((string)($row[$i]??''));if(empty($data['email'])||empty($data['name'])){$skipped++;continue;}if(User::whereRaw('LOWER(email)=?',[strtolower($data['email'])])->exists()){$skipped++;continue;}$dept=null;if(!empty($data['department']))$dept=Department::where('name',$data['department'])->value('id');User::create(['name'=>$data['name'],'email'=>strtolower($data['email']),'phone'=>$data['phone']??null,'role'=>in_array($data['role']??'viewer',['super-admin','department-admin','department-operator','viewer'],true)?$data['role']:'viewer','status'=>'active','department_id'=>$dept,'preferred_language'=>in_array($data['language']??'en',['en','gu'],true)?$data['language']:'en','password'=>Hash::make(bin2hex(random_bytes(12))),'must_change_password'=>true]);$created++;}$audit->log($r,'users.xlsx-imported',null,'Users imported from XLSX.',['created'=>$created,'skipped'=>$skipped]);return back()->with('success',"XLSX import complete: {$created} created, {$skipped} skipped.");}
 public function reportXlsx(Request $r,string $report,XlsxService $xlsx){abort_unless(in_array($report,['access','activity','notifications'],true),404);$controller=app(ReportController::class);$method=match($report){'access'=>'access','activity'=>'activity','notifications'=>'notifications'};$response=$controller->{$method}($r);$payload=json_decode($response->getContent(),true)?:[];$rows=$payload['rows']??$payload[$report]??[];if(!is_array($rows))$rows=[];$headers=[];$flat=[];foreach($rows as $row){$arr=is_array($row)?$row:(array)$row;if(!$headers)$headers=array_keys($arr);$flat[]=array_map(fn($v)=>is_scalar($v)||$v===null?(string)$v:json_encode($v,JSON_UNESCAPED_UNICODE),array_values($arr));}$tmp=tempnam(sys_get_temp_dir(),'report_').'.xlsx';$xlsx->write($headers,$flat,$tmp);return response()->download($tmp,"{$report}-report-".date('Ymd-His').'.xlsx')->deleteFileAfterSend(true);}
}
